Point2f u_scaled = Point2f(2.0f * u.x - 1.0f, 2.0f * u.y - 1.0f);
float radius = std::sqrt(std::max(std::abs(u_scaled.x), std::abs(u_scaled.y)));
if (radius > 1.0f) {
    float temp = 2.0f * u_scaled.x;
    u_scaled.x = 2.0f * u_scaled.y;
    u_scaled.y = temp;
    radius = std::sqrt(std::max(std::abs(u_scaled.x), std::abs(u_scaled.y)));
}
float angle = std::atan2(u_scaled.y, u_scaled.x);
return Point2f(radius * std::cos(angle), radius * std::sin(angle));

